values
  ('arterias-labszarfekely', 'Artériás lábszárfekély', '{"ischaemiás fekély","artériás fekély","kritikus végtagi ischaemia"}', 'Artériás fekély', 'Bőrgyógyászat és sebellátás', '{}', '{"crp","hba1c","chol"}', '{}', '{"artériás fekély","ischaemia","lábszárfekély"}', '{"brief_what": "A lábon kialakuló fekély az artériás keringés elégtelensége miatt. A szövet nem kap elég vért, ezért elhal — a seb nem a nyomástól, hanem a vérellátás hiányától keletkezik.", "brief_why": "A vénás fekélytől való elkülönítés a legfontosabb döntés ezen a területen: a vénásra adott kompresszió az artériás fekélynél elzárja a maradék keringést is, és végtagvesztéshez vezethet. A kezelés itt nem a sebbel kezdődik, hanem a keringés helyreállításával.", "when": ["Fájdalmas fekély a lábon, jellemzően a lábujjakon, a sarkon vagy a lábszár külső oldalán", "Nyugalmi fájdalom, amely felpolcolásra rosszabbodik és lelógatásra enyhül", "Hideg, sápadt vagy kékes láb", "Járási fájdalom, amely megállásra elmúlik"], "examine": ["Lábfej pulzusok tapintása — ha nem tapinthatók, a kompresszió tilos", "Boka-kar index mérése: ez adja meg a keringés mértékét", "A fekély helye és jellege: az artériás mély, kivájt szélű, gyakran a lábujjon vagy a nyomásnak kitett külső területen", "A bőr állapota: szőrtelen, vékony, fényes, hideg", "A fájdalom viselkedése: felpolcolásra rosszabbodik — ez a legjellemzőbb elkülönítő jel a vénástól", "Kapilláris újratelődés vizsgálata"], "labs": "Cukorbetegség és zsíranyagcsere vizsgálata, mert az alapbetegség kezelése a fekély kezelésének része. Fertőzés gyanújánál vérkép és CRP.", "ekg": "Nem a kórkép része, de az érelmeszesedés rendszerbetegség — a szív érintettsége gyakori.", "imaging": "Érultrahang, majd a keringés helyreállításának megítélésére érfestéses vizsgálat. Az elhúzódó gyógyulás önmagában is indokolja a képalkotást.", "scores": "A boka-kar index a keringés mértékét és a kompresszió biztonságosságát egyaránt megadja. Nagyon alacsony érték kritikus végtagi keringési zavart jelez, ami sürgős érsebészeti ellátást igényel.", "red_flags": ["Nyugalmi fájdalom, különösen éjszaka — kritikus végtagi keringési zavar", "Nem tapintható pulzus vagy nagyon alacsony boka-kar index", "Hideg, márványozott, elhaló láb", "Terjedő elhalás vagy fertőzés", "Hirtelen fájdalom, sápadtság, bénulás — akut érelzáródás, azonnali ellátás"], "apn_focus": ["A kompresszió tilalma a legfontosabb tudnivaló: az artériás fekélyre adott kompresszió a maradék keringést is elzárja", "A két fekélytípus elkülönítése a fájdalom viselkedése alapján: a vénás felpolcolásra enyhül, az artériás rosszabbodik", "A láb melegen tartása, de nem melegítéssel: a hőforrás az érzéketlen bőrön égési sérülést okoz", "A láb lelógatása enyhítheti a fájdalmat, de az ödémát fokozza — ez egyensúlyozás", "A dohányzás elhagyásának támogatása: ez a legerősebb befolyásolható tényező", "A száraz bőr ápolása, de az ujjközök szárazon tartása", "Az érsebészeti kivizsgálás sürgősségének felismerése"], "treatment": ["A keringés helyreállítása — ez az elsődleges, a sebkezelés csak ezután lehet eredményes", "Az érelmeszesedés kezelése: vérlemezke-gátló, koleszterincsökkentő, vérnyomás- és vércukor-beállítás", "Fájdalomcsillapítás, gyakran erős szerrel", "Óvatos sebkezelés: száraz elhalt szövet eltávolítása keringés nélkül ronthat az állapoton", "Fertőzés kezelése, ha jelen van"], "followup": ["A keringés ismételt megítélése", "A rizikótényezők kezelésének követése", "Lábápolási oktatás: az érzéketlen, rosszul keringő láb sérülékeny", "Érsebészeti gondozás"], "source_name": "Európai érsebészeti társaság ajánlása a krónikus végtagi keringési zavarról", "source_url": "https://esvs.org/guidelines/", "version": "2024", "updated": "2026-09-14", "evidence": "A keringés helyreállításának elsődlegessége a sebkezeléssel szemben erős ajánlás. A boka-kar index mérése minden lábszárfekélynél kötelező lépés a kompresszió megkezdése előtt."}'::jsonb, 'published', '1', false),
  ('sulyos-borreakcio', 'Súlyos gyógyszer okozta bőrreakció', '{"SJS","TEN","DRESS","Stevens-Johnson"}', 'Súlyos bőrreakció', 'Bőrgyógyászat és sebellátás', '{"news2"}', '{"crp","wbc","alt","krea"}', '{}', '{"gyógyszerreakció","SJS","TEN","DRESS"}', '{"brief_what": "Gyógyszer kiváltotta, életveszélyes bőr- és nyálkahártya-reakció. A leggyakoribb formák a hámleválással járó reakció és a szervi érintettséggel járó, elhúzódó forma.", "brief_why": "A halálozás jelentős, és a kimenetel azon múlik, milyen gyorsan hagyják el a kiváltó gyógyszert. Az első jelek megtévesztően enyhék: közönséges bőrkiütésnek látszanak, miközben napokon belül kiterjedt hámleválás alakulhat ki.", "when": ["Gyógyszerszedés kezdete után néhány nappal vagy héttel megjelenő kiütés", "Láz a kiütéssel együtt", "Nyálkahártya-érintettség: száj, szem, nemi szervek", "Fájdalmas, égő bőr", "Arcduzzanat, nyirokcsomó-megnagyobbodás"], "examine": ["A nyálkahártyák vizsgálata: száj, szem, nemi szervek — ez a legfontosabb elkülönítő jel a közönséges gyógyszerkiütéstől", "A bőr fájdalmassága és érzékenysége: a súlyos forma fáj, a közönséges viszket", "A hámleválás keresése: enyhe oldalirányú nyomásra a bőr elcsúszik", "A kiterjedés becslése, ahogy égésnél", "A gyógyszerszedés kezdetének pontos időpontja — az időbeli összefüggés kulcsfontosságú", "Arcduzzanat és nyirokcsomók: a szervi érintettséggel járó forma jele"], "labs": "Vérkép, májenzimek, vesefunkció — a szervi érintettséggel járó formánál ezek eltérnek, és az eozinofilszám gyakran emelkedett. Ionok és folyadékháztartás a kiterjedt hámleválásnál.", "ekg": "A monitorozás része súlyos állapotban.", "imaging": "Mellkasröntgen légúti érintettség gyanújánál.", "scores": "A kiterjedés alapján történik a besorolás, hasonlóan az égéshez. A súlyossági pontozó a kimenetel megítélésére szolgál.", "red_flags": ["Nyálkahártya-érintettség — ez emeli ki a közönséges kiütések közül", "Fájdalmas bőr, hámleválás", "Láz a kiütéssel együtt", "Szemtünetek — maradandó látáskárosodás alakulhat ki", "Arcduzzanat, nyirokcsomó-megnagyobbodás, szervi eltérés a laborban", "Gyorsan terjedő kiütés"], "apn_focus": ["A gyanú azonnali jelzése és a kiváltó gyógyszer leállításának kezdeményezése: a kimenetel ezen múlik", "A nyálkahártyák megnézése minden gyógyszerkiütésnél — ez a lépés dönti el, közönséges vagy súlyos reakcióról van-e szó", "A gyógyszerszedés kezdetének pontos rögzítése: az időbeli összefüggés a kórisme alapja", "A bőr kímélése: a kiterjedt hámleválás égési sérüléshez hasonló ellátást igényel — steril környezet, folyadékpótlás, hőmérséklet-szabályozás", "Szemészeti konzultáció kezdeményezése nyálkahártya-érintettségnél", "A kiváltó szer rögzítése a dokumentációban jól láthatóan: az újbóli adás súlyosabb reakciót okoz", "Fájdalomcsillapítás: a kiterjedt bőrkárosodás erősen fáj"], "treatment": ["A kiváltó gyógyszer azonnali elhagyása — ez a legfontosabb lépés", "Támogató kezelés: folyadékpótlás, hőmérséklet-szabályozás, sebkezelés", "Égési központba vagy intenzív osztályra szállítás kiterjedt formánál", "Szemészeti ellátás a maradandó károsodás megelőzésére", "Gyógyszeres kezelés a forma szerint, szakellátásban"], "followup": ["A kiváltó szer és a rokon vegyületek dokumentálása, a betegnek átadott írásos tájékoztatóval", "Szemészeti ellenőrzés: a szövődmények hónapokkal később is jelentkezhetnek", "Bőrgyógyászati gondozás", "A szervi érintettséggel járó forma utáni pajzsmirigy-ellenőrzés"], "source_name": "Nemzetközi bőrgyógyászati ajánlások a súlyos gyógyszer okozta bőrreakciók ellátásáról", "source_url": "https://www.eadv.org/guidelines", "version": "2024", "updated": "2026-09-14", "evidence": "A kiváltó gyógyszer korai elhagyása a kimenetel legfontosabb meghatározója. A nyálkahártya-érintettség a súlyos forma leghasználhatóbb korai jele."}'::jsonb, 'published', '1', false),
  ('bortalyog', 'Bőrtályog és furunculus', '{"tályog","furunculus","kelés","abscessus"}', 'Tályog', 'Bőrgyógyászat és sebellátás', '{"news2"}', '{"crp","wbc","hba1c"}', '{}', '{"tályog","furunculus","bőrfertőzés"}', '{"brief_what": "Gennygyülem a bőrben vagy a bőr alatti szövetben. A furunculus a szőrtüszőből indul, a tályog tágabb fogalom.", "brief_why": "A kezelés alapja a feltárás és a genny leeresztése, nem az antibiotikum. A szövődménymentes, feltárt tályog a legtöbb esetben antibiotikum nélkül gyógyul — ez gyakori félreértés.", "when": ["Fájdalmas, duzzadt, meleg csomó a bőrben", "Hullámzó tapintat — a genny jelenlétére utal", "Bőrpír a terület körül", "Láz nagyobb tályognál"], "examine": ["A hullámzó tapintat vizsgálata: ez különbözteti meg a tályogot a gyulladásos beszűrődéstől", "A terület kiterjedése és a környező bőrpír", "Elhelyezkedés: az arcon lévő, különösen az orr és a felső ajak közötti terület fokozott kockázatú", "Vitális paraméterek, ha láz is van", "Hajlamosító tényezők: cukorbetegség, immunhiány, ismétlődés"], "labs": "Szövődménymentes esetben nem szükséges. Ismétlődő tályognál vércukor és HbA1c — a fel nem ismert cukorbetegség gyakori háttértényező. Gennyből tenyésztés, ha a kezelés nem hoz javulást.", "ekg": "Nincs szerepe.", "imaging": "Ultrahang, ha a hullámzó tapintat bizonytalan — segít eldönteni, van-e leereszthető gennygyülem.", "scores": "Külön pontozó nincs.", "red_flags": ["Arcon, különösen az orr és a felső ajak közötti területen lévő tályog — a vénás elvezetés miatt koponyaűri szövődmény kockázata", "Terjedő bőrpír, láz, rossz általános állapot", "Ismétlődő tályogok — fel nem ismert cukorbetegség vagy immunhiány", "Végbél körüli tályog — mélyebb kiterjedés lehetősége", "Kézen lévő tályog — az ínhüvely érintettsége sürgős sebészi ellátást igényel"], "apn_focus": ["A hullámzó tapintat felismerése: ha van genny, a feltárás szükséges, és az antibiotikum önmagában nem gyógyít", "Meleg borogatás a kis, még nem érett tályognál — segíti a beolvadást", "A feltárás utáni sebkezelés: az üreg nyitva tartása a visszaképződés megelőzésére", "A saját kinyomás veszélyének elmagyarázása, különösen az arcon", "Ismétlődés esetén a vércukor ellenőrzésének felvetése", "A higiénia és a ruházat szerepe a hónalji és lágyéki formáknál"], "treatment": ["Feltárás és a genny leeresztése — ez a kezelés alapja", "Az üreg nyitva tartása vagy tamponálása", "Antibiotikum csak meghatározott esetben: terjedő fertőzés, láz, arcon lévő elhelyezkedés, immunhiány — a feltárt, szövődménymentes tályog nem igényli", "Fájdalomcsillapítás"], "followup": ["A seb gyógyulásának ellenőrzése", "Ismétlődés esetén a háttértényezők kivizsgálása", "Hajlamosító tényezők kezelése"], "source_name": "Nemzetközi lágyrészfertőzés-ajánlások a bőrtályogok kezeléséről", "source_url": "https://www.idsociety.org/practice-guideline/skin-and-soft-tissue-infections/", "version": "2024", "updated": "2026-09-14", "evidence": "A feltárás elsődlegessége az antibiotikummal szemben jól alátámasztott. A szövődménymentes, feltárt tályog antibiotikumos kezelése nem javítja a kimenetelt."}'::jsonb, 'published', '1', false),
  ('inkontinencia-borkarosodas', 'Inkontinencia okozta bőrkárosodás', '{"IAD","nedvesség okozta bőrkárosodás","pelenkadermatitis"}', 'IAD', 'Bőrgyógyászat és sebellátás', '{"braden"}', '{}', '{}', '{"inkontinencia","bőrkárosodás","ápolás"}', '{"brief_what": "A bőr gyulladása és sérülése a vizelettel vagy széklettel való tartós érintkezés miatt. A nedvesség felpuhítja a bőrt, a széklet enzimjei pedig maratják.", "brief_why": "Gyakran összekeverik a nyomási fekéllyel, pedig más a megelőzése és más a kezelése. A tévesztés következménye, hogy a beteg nyomáscsökkentő matracot kap, miközben a bőr továbbra is nedves marad — vagy fordítva.", "when": ["Bőrpír, égő érzés a nemi szervek körül, a fenéken vagy a combhajlatban", "Inkontinens, gyakran pelenkázott beteg", "Hasmenés, különösen tartós", "Nedves bőr, izzadás a bőrredőkben"], "examine": ["A bőrpír elhelyezkedése: az inkontinencia okozta a nedvességgel érintkező területeken jelenik meg, a nyomási fekély a csontos kiemelkedések fölött", "A szélek jellege: az inkontinencia okozta elmosódott szélű, a nyomási fekély élesebben határolt", "A mélység: az inkontinencia okozta felszínes, a bőr elvékonyodik, de nem képződik kráter", "Gombás felülfertőződés keresése: szatellita jellegű, apró gócok a széleken", "A nedvesség forrása: vizelet, széklet vagy mindkettő — a széklet károsítóbb"], "labs": "Nem szükséges.", "ekg": "Nincs szerepe.", "imaging": "Nincs szerepe.", "scores": "A nyomási fekély kockázatbecslő skálái a nedvesség tényezőjét is mérik, de a két kórkép megkülönböztetésére nem alkalmasak — azt a klinikai kép adja meg.", "red_flags": ["Mély, kráteres seb — ez már nyomási fekély, nem nedvesség okozta károsodás", "Terjedő bőrpír, láz — bakteriális felülfertőződés", "Nem javuló bőr megfelelő ápolás mellett", "Tartós hasmenés — a kiváltó ok keresendő"], "apn_focus": ["A két kórkép elkülönítése: a hely, a szélek és a mélység alapján — ez határozza meg, min kell változtatni", "A nedvesség eltávolítása a legfontosabb lépés: a g