-- ══ Ellenőrzés ═══════════════════════════════════════════
-- Tizenhat kidolgozott kórképnek kell megjelennie a szakterületen.
select slug, name,
  case when body ->> 'brief_what' is null then 'csonk' else 'kidolgozott' end as allapot,
  body ->> 'version' as forras_ev
from public.diseases
where specialty = 'Bőrgyógyászat és sebellátás' and status = 'published'
order by name;

-- A források átvezetése az irányelvtárba — a 0082 eseménykezelője ezt
-- magától elvégzi, de az ellenőrzés hasznos.
select g.title as forras, g.source_year as ev, g.from_disease_slug as korkep
from public.guidelines g
join public.diseases d on d.slug = g.from_disease_slug
where d.specialty = 'Bőrgyógyászat és sebellátás'
order by g.title;
